package org.apache.lucene.document;
import org.apache.lucene.geo.*;
import org.apache.lucene.document.*;
import org.apache.lucene.util.BytesRef;
public class Probe {
  public static void main(String[] args) throws Exception {
    int base = Integer.MAX_VALUE;
    double pLat = GeoEncodingUtils.decodeLatitude(base - 2);
    double pLon = GeoEncodingUtils.decodeLongitude(base - 2);
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    Polygon poly = new Polygon(new double[]{minLat,minLat,maxLat,maxLat,minLat}, new double[]{minLon,maxLon,maxLon,minLon,minLon});
    Component2D c = LatLonGeometry.create(poly);
    GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(c);
    int lat = GeoEncodingUtils.encodeLatitude(pLat);
    int lon = GeoEncodingUtils.encodeLongitude(pLon);
    System.out.println("predicate test("+lat+","+lon+")="+pred.test(lat,lon));
    System.out.println("contains="+c.contains(pLon,pLat));

    // replicate createSubBoxes details via reflection of grid
    java.lang.reflect.Field gf = pred.getClass().getDeclaredField("grid");
    gf.setAccessible(true);
    Object grid = gf.get(pred);
    Class<?> gc = grid.getClass();
    for (String n : new String[]{"latShift","lonShift","latBase","lonBase","maxLatDelta","maxLonDelta"}) {
      java.lang.reflect.Field f = gc.getDeclaredField(n); f.setAccessible(true);
      System.out.println(n+"="+f.get(grid));
    }
    java.lang.reflect.Field rf = gc.getDeclaredField("relations"); rf.setAccessible(true);
    byte[] rel = (byte[]) rf.get(grid);
    System.out.println("relations len="+rel.length+" vals="+java.util.Arrays.toString(rel));
    int ls = (int) get(gc,grid,"latShift"), os = (int) get(gc,grid,"lonShift"), lb=(int)get(gc,grid,"latBase"), ob=(int)get(gc,grid,"lonBase"), mld=(int)get(gc,grid,"maxLatDelta"), mod=(int)get(gc,grid,"maxLonDelta");
    for (int i=0;i<mld;i++) for (int j=0;j<mod;j++) {
      int boxMinLat = ((lb+i)<<ls)+Integer.MIN_VALUE;
      int boxMinLon = ((ob+j)<<os)+Integer.MIN_VALUE;
      int boxMaxLat = boxMinLat + (1<<ls) - 1;
      int boxMaxLon = boxMinLon + (1<<os) - 1;
      System.out.println("cell i="+i+" j="+j+" boxMinLat="+boxMinLat+" boxMaxLat="+boxMaxLat+" boxMinLon="+boxMinLon+" boxMaxLon="+boxMaxLon+" rel="+rel[i*mod+j]);
      try {
        System.out.println("   decoded minLat="+GeoEncodingUtils.decodeLatitude(boxMinLat)+" maxLat="+GeoEncodingUtils.decodeLatitude(boxMaxLat)+" minLon="+GeoEncodingUtils.decodeLongitude(boxMinLon)+" maxLon="+GeoEncodingUtils.decodeLongitude(boxMaxLon));
      } catch (Throwable t) { System.out.println("   decode error "+t); }
    }
  }
  static Object get(Class<?> c, Object o, String n) throws Exception { var f=c.getDeclaredField(n); f.setAccessible(true); return f.get(o); }
}

