  /**
   * Check whether the given point is within a distance of another point. NOTE: this operates
   * directly on the encoded representation of points.
   */
  public boolean test(int lat, int lon) {
    final GeoUtils.Grid cells = this.grid;
    final int lat2 = ((lat - Integer.MIN_VALUE) >>> cells.latShift);
    if (lat2 < cells.latBase || lat2 >= cells.latBase + cells.maxLatDelta) {
      return false;
    }
    int lon2 = ((lon - Integer.MIN_VALUE) >>> cells.lonShift);
    if (lon2 < cells.lonBase) { // wrap
      lon2 += 1 << (32 - cells.lonShift);
    }
    assert Integer.toUnsignedLong(lon2) >= cells.lonBase;
    assert lon2 - cells.lonBase >= 0;
    if (lon2 - cells.lonBase >= cells.maxLonDelta) {
      return false;
    }

    final int relation =
        cells.relations[(lat2 - cells.latBase) * cells.maxLonDelta + (lon2 - cells.lonBase)];
    if (relation == Relation.CELL_CROSSES_QUERY.ordinal()) {
      return SloppyMath.haversinSortKey(
              decodeLatitude(lat), decodeLongitude(lon), this.lat, this.lon)
          <= this.distanceKey;
    } else {
      return relation == Relation.CELL_INSIDE_QUERY.ordinal();
    }
  }
}

/** A predicate that checks whether a given point is within a component2D geometry. */
public static class Component2DPredicate {

  private final GeoUtils.Grid grid;
  private final Component2D tree;

  private Component2DPredicate(GeoUtils.Grid grid, Component2D tree) {
    this.grid = grid;
    this.tree = tree;
  }

  /**
   * Check whether the given point is within the considered polygon. NOTE: this operates directly
   * on the encoded representation of points.
   */
  public boolean test(int lat, int lon) {
    final GeoUtils.Grid cells = this.grid;
    final Component2D geometry = this.tree;
    final int lat2 = ((lat - Integer.MIN_VALUE) >>> cells.latShift);
    if (lat2 < cells.latBase || lat2 >= cells.latBase + cells.maxLatDelta) {
      return false;
    }
    int lon2 = ((lon - Integer.MIN_VALUE) >>> cells.lonShift);
    if (lon2 < cells.lonBase) { // wrap
      lon2 += 1 << (32 - cells.lonShift);
    }
    assert Integer.toUnsignedLong(lon2) >= cells.lonBase;
    assert lon2 - cells.lonBase >= 0;
    if (lon2 - cells.lonBase >= cells.maxLonDelta) {
      return false;
    }

    final int relation =
        cells.relations[(lat2 - cells.latBase) * cells.maxLonDelta + (lon2 - cells.lonBase)];
    if (relation == Relation.CELL_CROSSES_QUERY.ordinal()) {
      return geometry.contains(decodeLongitude(lon), decodeLatitude(lat));
    } else {
      return relation == Relation.CELL_INSIDE_QUERY.ordinal();
    }
  }
}

